window.PDD_DATA = window.PDD_DATA || [];
window.PDD_DATA = window.PDD_DATA.concat([{"num": 1, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Остановить автомобиль.", "Остановить автомобиль, впереди пешеходный переход через дорогу или улицу вблизи школы.", "Уступить дорогу автомобилям, движущимся справа от вас.", "Другие автомобили должны уступить вам дорогу."], "correct": 0, "expl": "Червоний восьмикутник — це знак STOP, встановлений міжнародною конвенцією про дорожні знаки. Це єдина восьмикутна форма на дорозі, тому її не можна сплутати з жодним іншим знаком навіть здалеку. Побачивши STOP, водій зобов'язаний повністю зупинити автомобіль незалежно від наявності іншого транспорту.", "explSpecific": "Правильна відповідь — «Остановить автомобиль»: STOP вимагає повної зупинки завжди, а не лише за певних умов. Варіант про пішохідний перехід біля школи описує інший (попереджувальний трикутний) знак; варіанти про поступання дорогою праворуч чи обов'язок інших вас пропустити стосуються знаку «Уступите дорогу», який на відміну від STOP не завжди вимагає зупинки.", "img": "q1.png"}, {"num": 2, "text": "Что должен сделать водитель, если этот знак сопровождается белой стоп-линией на дороге?", "topic": "Дорожні знаки та розмітка", "options": ["Остановиться на расстоянии оного автомобиля от стоп-линии.", "Остановиться за линией.", "Остановиться перед/на линии.", "Остановиться только в случае движения на главной дороге."], "correct": 2, "expl": "Якщо знак STOP супроводжується білою стоп-лінією на асфальті, саме лінія є точним місцем зупинки — перед нею, не заїжджаючи за неї.", "explSpecific": "Правильно — «Остановиться перед/на линии». Зупинка «за один автомобіль до лінії» невиправдано відсуває місце зупинки; «за линией» означає виїзд на перехрещувану проїжджу частину, що небезпечно; а прив'язка до руху головною дорогою суперечить суті STOP — він діє завжди, незалежно від типу вашої дороги.", "img": "q2.png"}, {"num": 3, "text": "Что должен сделать водитель, если этот знак не сопровождается белой стоп-линией на дороге?", "topic": "Дорожні знаки та розмітка", "options": ["Остановиться на расстоянии оного автомобиля от знака.", "Остановиться у знака.", "Остановиться за знаком.", "Остановиться только в случае движения на главной дороге."], "correct": 1, "expl": "Коли стоп-лінії немає, орієнтиром стає сам знак: водій зупиняється впритул до нього.", "explSpecific": "Правильно — «Остановиться у знака». Зупинка «за один автомобіль від знака» невиправдано відсуває зупинку без причини; «за знаком» означає проїзд повз нього; а умова «лише на головній дорозі» не відповідає суті STOP, який діє завжди.", "img": "q3.png"}, {"num": 4, "text": "Что означает этот знак в случае использования на перекрестке?", "topic": "Дорожні знаки та розмітка", "options": ["Уступить дорогу транспорту, движущемуся только справа от вас.", "Уступить дорогу транспорту, движущемуся по главной дороге.", "Замедлиться и уступит дорогу пешеходам.", "Уступить дорогу всем большегрузным автомобилям."], "correct": 1, "expl": "Перевернутий трикутник з червоною облямівкою — знак «Уступіть дорогу». На відміну від STOP він не вимагає обов'язкової повної зупинки — лише поступитися, якщо потрібно.", "explSpecific": "Правильно — «Уступить дорогу транспорту, движущемуся по главной дороге»: на перехресті цей знак стоїть на другорядній дорозі, тож поступитись треба всьому транспорту головної дороги, а не лише тому, що їде справа. Варіант про пішоходів помилковий — знак регулює відносини між транспортом; «вантажівкам» — вигаданий, нічим не обґрунтований критерій.", "img": "q4.png"}, {"num": 5, "text": "Что означает этот знак в случае использования на кольцевой развязке?", "topic": "Дорожні знаки та розмітка", "options": ["Уступить дорогу только автобусам и грузовым автомобилям.", "Уступить дорогу транспорту, движущемуся справа или уже находящемуся на кольцевой развязке.", "Уступить дорогу транспорту, движущемуся слева от вас.", "Уступить дорогу только велосипедистам и мотоциклистам."], "correct": 1, "expl": "На кільцевій розв'язці той самий знак «Уступіть дорогу» стосується транспорту, який вже рухається по колу.", "explSpecific": "Правильно — «Уступить дорогу транспорту, движущемуся справа или уже находящемуся на кольцевой развязке»: в Ірландії рух лівосторонній, тому на кільці транспорт рухається за годинниковою стрілкою і під'їжджає до в'їзду праворуч. «Тільки автобусам і вантажівкам» звужує правило до окремих типів транспорту, хоча воно стосується всіх; «зліва» — прямо протилежний, невірний бік для лівостороннього руху.", "img": "q5.png"}, {"num": 6, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди улица с двухсторонним движением.", "Впереди автострада.", "Впереди полоса обгона.", "Движение только прямо."], "correct": 3, "expl": "Синій круг з білою стрілкою — обов'язкова вказівка напрямку руху. На відміну від червоного (заборона) чи жовтого (попередження), синій колір наказує конкретну дію.", "explSpecific": "Правильно — «Движение только прямо»: стрілка вказує єдиний дозволений напрямок. Інші варіанти («вулиця з двостороннім рухом», «автострада попереду», «смуга для обгону») описують інформаційні прямокутні знаки, які мають геть іншу форму й колір.", "img": "q6.png"}, {"num": 7, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Разрешается движение только налево.", "Приоритет транспорта, движущегося справа.", "Объезд вперед и налево.", "Автострада слева."], "correct": 0, "expl": "Синій круг зі стрілкою — обов'язковий напрямок руху, що наказує конкретну дію на відміну від попереджувальних чи заборонних знаків.", "explSpecific": "Правильно — «Разрешается движение только налево»: стрілка на синьому колі показує єдиний дозволений напрямок. «Пріоритет транспорту праворуч» стосується інших за формою й кольором знаків пріоритету; «об'їзд вперед і ліворуч» та «автострада зліва» — це інформаційні знаки-покажчики, а не накази єдиного напрямку.", "img": "q7.png"}, {"num": 8, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Разрешено движение только на право.", "Обгон только справа.", "Объезд вперед и направо.", "Главная дорога, присоединяющаяся справа."], "correct": 0, "expl": "Синій круг зі стрілкою праворуч наказує рухатися лише в цьому напрямку — так само, як і його дзеркальний варіант ліворуч.", "explSpecific": "Правильно — «Разрешено движение только на право». «Обгін лише справа» описує геть інший, заборонний знак обгону; «об'їзд вперед і праворуч» і «головна дорога, що приєднується справа» — це інформаційні знаки-покажчики іншої форми, не наказова стрілка єдиного напрямку.", "img": "q8.png"}, {"num": 9, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди крутой поворот направо.", "Впереди объезд налево.", "Впереди односторонние движение налево.", "Впереди поворот налево."], "correct": 3, "expl": "Трикутник з червоною облямівкою — попереджувальний знак: він не наказує напрямок, а лише попереджає про особливість дороги попереду, щоб водій завчасно знизив швидкість.", "explSpecific": "Правильно — «Впереди поворот налево»: символ показує вигин дороги ліворуч. «Крутой поворот направо» переплутує і напрямок (тут ліворуч), і різкість повороту, для якої є окремий знак з іншим кутом стрілки; «об'їзд ліворуч» і «одностороннє ліворуч» — це сигнатури інших знаків із геть іншим виглядом.", "img": "q9.png"}, {"num": 10, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди объезд направо.", "Впереди поворот направо.", "Впереди крутой поворот направо.", "Впереди одностороннее движение направо."], "correct": 1, "expl": "Попереджувальний трикутник зі стрілкою-вигином показує напрямок повороту дороги попереду, без наказу конкретної дії водію.", "explSpecific": "Правильно — «Впереди поворот направо»: стрілка показує звичайний поворот праворуч. «Об'їзд праворуч» — інший символ (стрілка навколо перешкоди); «крутой поворот» позначається різкішим кутом стрілки на іншому знаку; «одностороннє праворуч» — вже прямокутний інформаційний знак, не трикутник.", "img": "q10.png"}, {"num": 11, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Крутой спуск налево.", "Езжайте налево.", "Держитесь левой стороны.", "Поворот налево запрещен."], "correct": 2, "expl": "Синій знак зі стрілкою вниз-ліворуч біля розділювача чи острівця безпеки вказує обов'язковий бік об'їзду перешкоди.", "explSpecific": "Правильно — «Держитесь левой стороны»: знак наказує обходити перешкоду саме зліва. «Крутой спуск» — геть інша категорія (попередження про ухил, трикутник); «Езжайте налево» неточно передає сенс обов'язкового об'їзду; «Поворот налево запрещен» — заборонний знак іншої форми (перекреслене червоне коло).", "img": "q11.png"}, {"num": 12, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Транспортная развязка слева.", "Крутой спуск слева.", "Поворот направо запрещен.", "Держитесь правой стороны."], "correct": 3, "expl": "Дзеркальний варіант знаку обов'язкового об'їзду перешкоди — стрілка вниз-праворуч наказує обхід саме з правого боку.", "explSpecific": "Правильно — «Держитесь правой стороны». Інші варіанти («транспортна розв'язка зліва», «крутий спуск зліва», «поворот направо заборонено») описують знаки геть іншої форми й кольору — попереджувальні чи заборонні, а не синій наказовий знак об'їзду.", "img": "q12.png"}, {"num": 13, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Объезд препятствий с обеих сторон.", "Впереди двухстороннее движение.", "Улица с односторонним движением.", "Впереди проезжая часть с двухсторонним движением."], "correct": 0, "expl": "Синій знак зі стрілками в обидва боки навколо перешкоди дозволяє об'їжджати її і зліва, і справа — на відміну від знаків «тільки зліва» чи «тільки справа».", "explSpecific": "Правильно — «Объезд препятствий с обеих сторон»: подвійна стрілка означає вибір водія. Інші варіанти («двостороннній рух», «одностороння вулиця», «проїжджа частина з двостороннім рухом») стосуються геть іншої категорії знаків — характеру руху на дорозі, а не об'їзду конкретної перешкоди.", "img": "q13.png"}, {"num": 14, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди объезд запрещен.", "Впереди тупик.", "Парковка запрещена.", "Обгон запрещен."], "correct": 0, "expl": "Знак з перекресленою стрілкою об'їзду навколо перешкоди означає заборону об'їзду в цьому місці — рухатися можна лише прямо, без обходу перешкоди збоку.", "explSpecific": "Правильно — «Впереди объезд запрещен»: перекреслена стрілка об'їзду прямо забороняє маневр обходу. «Тупик» позначається геть іншим символом (літера T з перекладиною); «парковка заборонена» і «обгін заборонений» — окремі, добре впізнавані круглі заборонні знаки з іншими піктограмами.", "img": "q14.png"}, {"num": 15, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Поворот направо запрещен.", "Впереди опасный поворот направо.", "Поворот запрещен в рабочие часы.", "Впереди поворот запрещен."], "correct": 0, "expl": "Червоне коло зі стрілкою повороту, перекресленою навскіс, — заборонний знак: конкретний маневр заборонено постійно, якщо немає додаткової таблички з обмеженням у часі.", "explSpecific": "Правильно — «Поворот направо запрещен». «Попереду небезпечний поворот» описує геть інший, попереджувальний трикутний знак; «заборонено лише в робочі години» додає умову, якої на самому знаку немає (для цього потрібна окрема табличка); «попереду поворот заборонено» без напрямку неточно передає, що знак стосується саме правого повороту.", "img": "q15.png"}, {"num": 16, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Поворот на право запрещен.", "Поворот налево запрещен.", "Разрешается движение только направо.", "Тупик слева."], "correct": 1, "expl": "Дзеркальний варіант попереднього знаку — перекреслена стрілка лівого повороту забороняє саме цей маневр.", "explSpecific": "Правильно — «Поворот налево запрещен»: піктограма показує саме лівий поворот. «Заборона повороту праворуч» переплутує напрямок; «дозволено лише праворуч» описує синій наказовий знак іншого кольору й сенсу (дозвіл, а не заборона); «тупик зліва» — геть інший інформаційний знак.", "img": "q16.png"}, {"num": 17, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Маневрирование задним ходом запрещено.", "Въезд в туннель запрещен.", "Разворот запрещен.", "Двустороннее движение запрещено."], "correct": 2, "expl": "Червоне коло зі стрілкою-петлею розвороту, перекресленою навскіс, забороняє саме розворот (U-turn) у цьому місці.", "explSpecific": "Правильно — «Разворот запрещен»: піктограма — це стрілка, що вигинається на 180°. «Заборона руху заднім ходом» показувала б пряму стрілку назад; «заборона в'їзду в тунель» і «заборона двостороннього руху» позначаються геть іншими символами, не петлею розвороту.", "img": "q17.png"}, {"num": 18, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Длина автомагистрали составляет 30 километров.", "Минимальная скорость составляет 30 км/ч.", "Парковка в течение более 30 минут запрещена.", "Максимальная скорость составляет 30 км/ч."], "correct": 3, "expl": "Червоне коло з числом на білому тлі — знак обмеження максимальної швидкості. Число завжди означає верхню межу дозволеної швидкості в км/год, а не мінімум, відстань чи час.", "explSpecific": "Правильно — «Максимальная скорость составляет 30 км/ч». «Довжина автомагістралі» і «понад 30 хвилин заборонено» описують геть інші знаки (інформаційні чи паркувальні); «мінімальна швидкість» позначається знаком іншого кольору — синім колом, бо мінімум це наказ, а не заборона перевищення.", "img": "q18.png"}, {"num": 19, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Длина автомагистрали составляет 50 километров.", "Максимальная скорость составляет 50 км/ч.", "Максимальное расстояние между транспортными средствами составляет 50 метров.", "Минимальная скорость составляет 50 км/ч."], "correct": 1, "expl": "Той самий тип знаку — червоне коло з числом — завжди задає верхню межу дозволеної швидкості.", "explSpecific": "Правильно — «Максимальная скорость составляет 50 км/ч». Довжина дороги, дистанція між автомобілями чи мінімальна швидкість позначаються знаками іншого кольору й форми, а не червоним колом з числом.", "img": "q19.png"}, {"num": 20, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Максимальная скорость составляет 60 км/ч.", "Парковка в течение более 60 минут запрещена.", "Минимальная скорость составляет 60 км/ч.", "До перекрестка 60 метров."], "correct": 0, "expl": "Червоне коло з числом — обмеження максимальної швидкості, незмінне правило незалежно від конкретного числа на знаку.", "explSpecific": "Правильно — «Максимальная скорость составляет 60 км/ч». «Понад 60 хвилин заборонено» і «до перехрестя 60 метрів» стосуються геть інших за формою знаків (паркування, інформаційні); «мінімальна швидкість» — це синій, а не червоний знак.", "img": "q20.png"}, {"num": 21, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Максимальная скорость составляет 80 км/ч.", "До автострады 80 метров.", "До конца автострады 80 метров.", "Минимальная скорость составляет 80 км/ч."], "correct": 0, "expl": "Червоне коло з числом — обмеження максимальної швидкості; відстані до об'єктів позначаються прямокутними інформаційними знаками іншого вигляду.", "explSpecific": "Правильно — «Максимальная скорость составляет 80 км/ч». «До автостради 80 метрів» і «до кінця автостради 80 метрів» — це інформаційні знаки-покажчики; «мінімальна швидкість» — знак іншого кольору (синій).", "img": "q21.png"}, {"num": 22, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Минимальная скорость составляет 100 км/ч.", "Максимальная скорость составляет 100 км/ч.", "Длина автомагистрали составляет 100 километров.", "До скоростной автострады 100 метров."], "correct": 1, "expl": "Червоне коло з числом завжди означає максимально дозволену швидкість у км/год на цій ділянці.", "explSpecific": "Правильно — «Максимальная скорость составляет 100 км/ч». «Мінімальна швидкість» — синій наказовий знак; «довжина автомагістралі» і «до швидкісної автостради 100 метрів» — інформаційні прямокутні знаки, не круглі заборонні.", "img": "q22.png"}, {"num": 23, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Длина автомагистрали составляет 120 километров", "Минимальная скорость составляет 120 км/ч", "Максимальная скорость составляет 120 км/ч.", "Через 120 метров регулирование автомобильного потока."], "correct": 2, "expl": "Червоне коло з числом — це завжди максимальна, а не мінімальна швидкість, і не відстань чи довжина дороги.", "explSpecific": "Правильно — «Максимальная скорость составляет 120 км/ч». «Довжина автомагістралі 120 км» і «регулювання потоку через 120 метрів» — інформаційні знаки; «мінімальна швидкість» позначається синім колом, а не червоним.", "img": "q23.png"}, {"num": 24, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Стоянка для людей с ограниченными возможностями.", "В указанное время стоянка разрешена.", "Максимальная продолжительность стоянки составляет 1 час в указанные промежутки времени.", "Стоянка запрещена в указанное время."], "correct": 1, "expl": "Синій знак «P» з додатковою табличкою часу означає режим дозволеної стоянки — сама табличка встановлює, коли саме стоянка можлива.", "explSpecific": "Правильно — «В указанное время стоянка разрешена»: табличка задає вікно, коли стоянка дозволена. Варіант про інвалідів вимагає окремого символу (піктограма крісла колісного), якого тут немає; «максимум 1 година» і «заборонено у вказаний час» описують протилежні за змістом таблички.", "img": "q24.png"}, {"num": 25, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Парковка личных транспортных средств запрещена.", "Парковка запрещена.", "Парковка разрешена.", "Парковка транспортных средств коммунального обслуживания запрещена."], "correct": 1, "expl": "Синій круг з червоною облямівкою і діагональною рискою через літеру P — стандартний знак «Стоянка заборонена», що діє для всіх транспортних засобів без винятку.", "explSpecific": "Правильно — «Парковка запрещена» без обмежень за типом транспорту. Уточнення «лише приватного» чи «лише комунального транспорту» вигадані — знак не розрізняє типи транспорту; «стоянка дозволена» — протилежне за змістом трактування.", "img": "q25.png"}, {"num": 26, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["В указанное время дорога закрыта.", "Скорость автострада. Остановка или стоянка в указанное время запрещены.", "Впереди перекресток с равнозначными дорогами.", "Пешеходная улица. Доступ транспортным средствам запрещен."], "correct": 1, "expl": "Знак із табличкою часу на швидкісній дорозі означає, що зупинка й стоянка заборонені саме у вказані години, а в інший час можуть бути дозволені.", "explSpecific": "Правильно — варіант про заборону зупинки/стоянки у вказаний час на швидкісній дорозі. «Дорога закрита» — геть інша заборона (проїзду взагалі); «перехрестя з рівнозначними дорогами» і «пішохідна вулиця» не мають стосунку до розкладу паркування.", "img": "q26.png"}, {"num": 27, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Стояночный диск не работает в указанное промежутки времени.", "Стоянка запрещена в указанные промежутки времени.", "Стоянка без стояночного диска запрещена в указанные промежутки времени.", "Стояночный диск работает в указанные промежутки времени."], "correct": 3, "expl": "Знак стоянки з піктограмою парковочного диска і табличкою часу означає, що в зазначені години стоянка дозволена лише з виставленим на диску часом прибуття.", "explSpecific": "Правильно — «Стояночный диск работает в указанные промежутки времени», тобто диск потрібен саме в ці години. Інші варіанти або заперечують дію диска, або взагалі забороняють стоянку, хоча табличка часу на знаку з диском означає режим його обов'язкового використання.", "img": "q27.png"}, {"num": 28, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Частные транспортные средства могут подбирать или высаживать пассажиров.", "Место предназначено для стоянки такси.", "Поворот налево разрешен только такси.", "Честная стоянка разрешена только когда стоянка для такси свободна."], "correct": 1, "expl": "Синій прямокутний знак зі словом «TAXI» чи піктограмою таксі позначає зарезервоване місце стоянки виключно для таксі.", "explSpecific": "Правильно — «Место предназначено для стоянки такси». Приватний транспорт не має права навіть висаджувати пасажирів у цій зоні; поворот ліворуч тут ні до чого — знак про стоянку; а «коли місце вільне» — вигадана умова, зона зарезервована завжди.", "img": "q28.png"}, {"num": 29, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Велосипедисты должны слезть с велосипеда.", "Дорожка предназначена для мотоциклистов.", "Начало велосипедной дорожки.", "Велосипедный трек."], "correct": 2, "expl": "Синій круглий знак з піктограмою велосипеда позначає обов'язкову велосипедну доріжку — окрему смугу, якою велосипедисти зобов'язані користуватися.", "explSpecific": "Правильно — «Начало велосипедной дорожки». «Злізти з велосипеда» позначається іншим знаком; «для мотоциклістів» переплутує тип транспорту — піктограма саме велосипеда; «велосипедний трек» — це спортивний об'єкт, а не елемент дорожньої інфраструктури.", "img": "q29.png"}, {"num": 30, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Попутная полоса движения автобусов справа.", "Встречная полоса движения автобусов справа.", "Автобусам разрешено пересекать велосипедную дорожку.", "Автобусы могут появиться справа."], "correct": 1, "expl": "Прямокутний синій знак зі стрілкою і піктограмою автобуса, спрямованою назустріч загальному потоку, позначає смугу зустрічного руху автобусів.", "explSpecific": "Правильно — «Встречная полоса движения автобусов справа»: напрямок стрілки на піктограмі протилежний вашому руху. «Попутна» була б вірною лише за збігу напрямків; «перетин велодоріжки» і «можуть з'явитися» — формулювання для геть інших попереджувальних знаків.", "img": "q30.png"}, {"num": 31, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Остановиться и ждать указаний регулировщика.", "Впереди детская поликлиника.", "Впереди школа.", "Впереди детская площадка."], "correct": 0, "expl": "Цей знак пов'язаний з чергуванням шкільного регулювальника («lollipop patrol») біля школи: коли він піднімає жезл із написом STOP, водій зобов'язаний зупинитися й чекати сигналу, а не просто бути обережним.", "explSpecific": "Правильно — «Остановиться и ждать указаний регулировщика». Варіанти про дитячу поліклініку, школу чи майданчик описують лише МІСЦЕ поруч, а не дію, якої вимагає знак — обов'язкову зупинку за командою регулювальника.", "img": "q31.png"}, {"num": 32, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди пешеходная улица- движение разрешено исключительно в указанное время.", "Впереди скоростная автострада. Остановка или стоянка в указанное время запрещены.", "Стояка запрещена в указанное время.", "Доступ разрешен только автобусам и такси в указанное время."], "correct": 0, "expl": "Знак пішохідної вулиці з додатковою табличкою часу означає, що виїзд транспорту на неї дозволений лише у визначені години, а в решту часу вулиця повністю пішохідна.", "explSpecific": "Правильно — «Впереди пешеходная улица... разрешено исключительно в указанное время». «Швидкісна автострада» і «стоянка заборонена» описують геть інші за формою й кольором знаки; «доступ лише автобусам і таксі» — вигаданий виняток, якого немає на цьому знаку.", "img": "q32.png"}, {"num": 33, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Трехосные транспортные средства запрещены.", "Максимальная разрешенная масса транспортного средства- 3 тонны.", "Минимальная разрешенная масса транспортного средства- 3 тонны.", "Разрешается движение только трехосных транспортных средств."], "correct": 1, "expl": "Трикутна табличка з числом і зображенням вантажівки означає обмеження за масою — максимально дозволену вагу транспорту, а не мінімальну чи кількість осей.", "explSpecific": "Правильно — «Максимальная разрешенная масса транспортного средства — 3 тонны». «Трьохосні заборонені» плутає масу з кількістю осей; «мінімальна маса» і «дозволено лише трьохосним» перевертають сенс заборонного знаку на протилежний — дозвільний.", "img": "q33.png"}, {"num": 34, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Разрешается въезд транспортных средств массой свыше 10 тонн.", "Запрещается въезд транспортных средств массой свыше 10 тонн.", "Запрещается въезд транспортных средств массой ниже 10 тонн.", "Предупреждение о встречном транспорте свыше 10 тонн."], "correct": 1, "expl": "Червоне коло з числом і перекресленою піктограмою вантажівки — заборона в'їзду для транспорту, маса якого перевищує вказану цифру (стандартна логіка знаку ваги: обмежується важкий транспорт, а не легкий).", "explSpecific": "Правильно — «Запрещается въезд транспортных средств массой свыше 10 тонн». «Дозволяється» суперечить забороняючому червоному кольору; «нижче 10 тонн заборонено» перевертає логіку знаку на протилежну — заборонні знаки ваги завжди обмежують важчий, а не легший транспорт; «попередження про зустрічний транспорт» — geть інша (жовта трикутна) категорія знаків.", "img": "q34.png"}, {"num": 35, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Разрешается въезд транспортных средств имеющих более 5 осей.", "Запрещается въезд транспортных средств имеющих менее 5 осей.", "Запрещается въезд транспортных средств имеющих более 5 осей.", "Разрешается въезд транспортных средств имеющих менее 5 осей."], "correct": 2, "expl": "Аналогічний заборонний знак, але обмеження стосується кількості осей транспортного засобу, а не маси.", "explSpecific": "Правильно — заборона для транспорту з більше ніж 5 осями. Варіанти «дозволяється» суперечать червоному забороняючому кольору знаку; «менше 5 осей заборонено» перевертає числову умову на протилежну.", "img": "q35.png"}, {"num": 36, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Минимальная разрешённая высота транспортного средства указана на знаке- Ограничение высоты транспортного средства.", "Максимально разрешённая длина транспортного средства указана на знаке- Ограничение высоты транспортного средства.", "Минимальная разрешённая длина транспортного средства указана на знаке- Ограничение высоты транспортного средства.", "Максимально разрешённая высота транспортного средства указана на знаке- Ограничение высоты транспортного средства."], "correct": 3, "expl": "Знак з числом і стрілками вгору-вниз обмежує саме висоту транспорту, що проїжджає під мостом чи в тунелі, а не довжину.", "explSpecific": "Правильно — «Максимально разрешённая высота». Варіанти про довжину плутають розмір, який регулює знак; «мінімальна висота» суперечить типовій меті знаку — попередити про низьку перешкоду згори.", "img": "q36.png"}, {"num": 37, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Запрещена стоянка транспортных средств, масса которых ниже указанной.", "Стоянка в зоне погрузки запрещена.", "Запрещен проезд другого транспорта массой, превышающей указанную.", "Запрещена стоянка транспортных средств масса которых выше указанной."], "correct": 3, "expl": "Знак стоянки з числом маси обмежує стоянку для транспорту, важчого за вказану цифру — це типово захищає вузькі вулиці від великогабаритних вантажівок.", "explSpecific": "Правильно — заборона стоянки для транспорту, маса якого вища за вказану. «Нижче вказаної» перевертає умову; «зона навантаження» і «заборона проїзду» описують геть інші за призначенням знаки.", "img": "q37.png"}, {"num": 38, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Стоянка в два ряда запрещена.", "Конец дороги с двухсторонним движением.", "Остановка/ стоянка справа.", "Обгон запрещен."], "correct": 3, "expl": "Червоне коло з піктограмою двох автомобілів поруч (один чорний, один червоний) — універсальний знак заборони обгону.", "explSpecific": "Правильно — «Обгон запрещен»: піктограма двох машин символізує заборонений маневр випередження. «Стоянка в два ряди», «кінець двостороннього руху» і «зупинка справа» мають геть інші піктограми — літеру P чи стрілки, не силуети двох автомобілів.", "img": "q38.png"}, {"num": 39, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Только автобусы и велосипедисты могут парковаться в указанное время.", "Только велосипедисты и автобусы могут использовать полосу в указанное время.", "Только автобусы, велосипедисты и такси могут использовать полосу движения вне указанного времени.", "Только автобусы, велосипедисты и такси могут использовать полосу движения в указанное время."], "correct": 3, "expl": "Прямокутний синій знак з піктограмами автобуса, велосипеда й таксі та табличкою часу дозволяє рух цією смугою лише перерахованим категоріям транспорту й лише у вказаний проміжок.", "explSpecific": "Правильно — «Только автобусы, велосипедисты и такси... в указанное время». «Поза вказаним часом» перевертає умову таблички; варіанти про стоянку чи лише дві категорії транспорту не відповідають повному переліку піктограм і призначенню знаку смуги руху.", "img": "q39.png"}, {"num": 40, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Эта полоса предназначена только для двухъярусных автобусов и велосипедов.", "Велосипедисты и автобусы должны повернуть налево.", "Впереди слева есть боковая попутная полоса движения автобусов и велосипедов.", "Стоянка разрешена только для автобусов и велосипедов."], "correct": 2, "expl": "Знак зі стрілкою, що відгалужується ліворуч, і піктограмами автобуса й велосипеда попереджає про підхід бокової смуги для цих видів транспорту.", "explSpecific": "Правильно — «Впереди слева... попутная полоса автобусов и велосипедов». «Тільки для двоярусних автобусів» — вигадка; «повинні повернути ліворуч» невірно трактує інформаційну стрілку як наказ; «стоянка дозволена» суперечить призначенню знаку смуги руху.", "img": "q40.png"}, {"num": 41, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Стоянка для автобусов и велосипедов слева.", "Впереди велосипедная полоса, которую могут пересекать только автобусы.", "Впереди слева попутная полоса движения автобусов и велосипедная дорожка.", "Велосипедам и автобусам запрещено уходить налево."], "correct": 2, "expl": "Той самий тип знаку смуги для автобусів і велосипедистів, розташованої зліва попереду.", "explSpecific": "Правильно — «Впереди слева попутная полоса автобусов и велосипедная дорожка». «Стоянка зліва» неправильно трактує смугу руху як місце стоянки; «перетин лише автобусами» і «заборона повороту ліворуч» не відповідають призначенню суто інформаційного знаку.", "img": "q41.png"}, {"num": 42, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Автобусы должны уступить дорогу другому транспорту впереди.", "Впереди справа есть полоса движения автобусов и велосипедная полоса.", "Велосипедисты должны уступить дорогу автобусам впереди.", "Автобусы должны уступить дорогу велосипедистам впереди."], "correct": 1, "expl": "Інформаційний знак про розташування смуги для автобусів і велосипедистів праворуч попереду — без наказу пріоритету між ними.", "explSpecific": "Правильно — «Впереди справа есть полоса движения автобусов и велосипедная полоса». Варіанти про обов'язок поступатися дорогою одне одному вигадують стосунки пріоритету, яких немає на цьому суто інформаційному знаку.", "img": "q42.png"}, {"num": 43, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Попутная полоса движения автобусов слева.", "Автобусы могут заблокировать видимость велосипедистов водителем.", "Попутная полоса движения автобусов справа.", "Впереди встречная полоса движения автобусов."], "correct": 2, "expl": "Стрілка на піктограмі автобусної смуги, що збігається з напрямком вашого руху, означає попутну (а не зустрічну) смугу.", "explSpecific": "Правильно — «Попутная полоса движения автобусов справа» (стрілка збігається з напрямком руху). «Зліва» переплутує бік; «можуть блокувати видимість велосипедистів» і «зустрічна смуга» описують інші попереджувальні чи протилежні за напрямком знаки.", "img": "q43.png"}, {"num": 44, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Попутная полоса движения автобусов справа.", "Встречная полоса движения автобусов справа.", "Автобусам разрешено пересекать велосипедную дорожку.", "Автобусы могут появиться справа."], "correct": 1, "expl": "Стрілка на піктограмі автобусної смуги, спрямована НАЗУСТРІЧ загальному потоку, позначає смугу зустрічного руху автобусів, навіть якщо вона розташована праворуч від вас.", "explSpecific": "Правильно — «Встречная полоса движения автобусов справа». «Попутна» була б вірною лише за збігу напрямків стрілки й вашого руху; «перетин велодоріжки» і «можуть з'явитися» — формулювання для геть інших знаків.", "img": "q44.png"}, {"num": 45, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Трамвайная линия слева.", "Парковка внутри белой разметки запрещена.", "Автобусная и трамвайная полоса слева.", "Трамваи выезжают слева."], "correct": 0, "expl": "Знак з піктограмою трамвая та стрілкою ліворуч позначає розташування трамвайної колії.", "explSpecific": "Правильно — «Трамвайная линия слева». «Заборона парковки в межах розмітки» описує геть інший заборонний знак; «автобусна і трамвайна смуга» додає автобуси, яких немає на піктограмі; «трамваї виїжджають зліва» неточно передає статичне розташування колії як маневр виїзду.", "img": "q45.png"}, {"num": 46, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Трамвайная линия слева.", "Трамвайная линия справа.", "Впереди попутная полоса движения автобусов.", "Стоянка разрешена только в пределах белой полосы."], "correct": 1, "expl": "Дзеркальний варіант знаку трамвайної колії — стрілка вказує на розташування справа.", "explSpecific": "Правильно — «Трамвайная линия справа». «Зліва» переплутує бік; «попутна смуга автобусів» і «стоянка в межах білої смуги» описують геть інші піктограми.", "img": "q46.png"}, {"num": 47, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди перекресток с главной дорогой.", "Впереди перекресток с железнодорожным переездом.", "Впереди перекресток со второстепенной дорогой.", "Впереди перекресток с равнозначной дорогой."], "correct": 2, "expl": "Трикутний попереджувальний знак перехрестя показує тип дороги, що приєднується: тонша лінія на символі позначає другорядну дорогу.", "explSpecific": "Правильно — «Впереди перекресток со второстепенной дорогой». «Головна дорога» переплутує, яка саме лінія товща на символі; «залізничний переїзд» і «рівнозначна дорога» показуються геть іншими символами.", "img": "q47.png"}, {"num": 48, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Развилка, на которой тяжелые транспортные средства должны ехать на лево.", "Развилка, на которой главная дорога уходит влево.", "Развилка, на которой главная дорога уходит вправо.", "Развилка, на которой транспортные средства должны ехать на лево."], "correct": 1, "expl": "Трикутний знак розвилки з потовщеною лінією одного з напрямків показує, куди продовжується головна дорога на розгалуженні.", "explSpecific": "Правильно — «Развилка, на которой главная дорога уходит влево» (товща лінія веде ліворуч). «Праворуч» переплутує напрямок; «важкий транспорт ліворуч» і «всі ТЗ ліворуч» вигадують накази, яких немає на попереджувальному знаку.", "img": "q48.png"}, {"num": 49, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди ряд пересечений с равнозначными дорогами.", "Тупик с обеих сторон.", "Впереди участки обеспечения принудительного снижения скорости транспорта.", "Впереди дороги закрыты с обеих сторон."], "correct": 0, "expl": "Цей знак попереджає про кілька перехресть з рівнозначними дорогами поспіль на ділянці попереду.", "explSpecific": "Правильно — «Впереди ряд пересечений с равнозначными дорогами». «Тупик з обох боків» і «дороги закриті» описують геть інші символи; «зниження швидкості» — окрема категорія знаків (лежачі поліцейські), не перехрестя.", "img": "q49.png"}, {"num": 50, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди главная дорога.", "Впереди перекресток со второстепенной дорогой.", "Впереди перекресток с равнозначной дорогой.", "Впереди железнодорожный переезд."], "correct": 2, "expl": "Обидві лінії символу перехрестя однаково товсті, що означає рівнозначність доріг — і, відповідно, правило «перешкода справа».", "explSpecific": "Правильно — «Впереди перекресток с равнозначной дорогой». «Головна» і «другорядна дорога» вимагали б різної товщини ліній на піктограмі; «залізничний переїзд» — геть інший символ.", "img": "q50.png"}, {"num": 51, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди Т-образный перекресток со слиянием автомобильных потоков.", "Впереди Т-образный перекресток со второстепенной дорогой.", "Впереди Т-образный перекресток с дорогой с двухсторонним движением.", "Впереди Т-образный перекресток с равнозначной дорогой."], "correct": 3, "expl": "Т-подібний символ з однаково товстими лініями обох напрямків означає перехрестя рівнозначних доріг.", "explSpecific": "Правильно — «Впереди Т-образный перекресток с равнозначной дорогой». «Злиття потоків» описує інший символ (дві стрілки, що зливаються); «другорядна дорога» і «двосторонній рух» вимагали б інших деталей піктограми.", "img": "q51.png"}, {"num": 52, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди развилка со второстепенными дорогами.", "Впереди развилка с дорогой с двухсторонним движением.", "Впереди второстепенная дорога.", "Впереди развилка с равнозначными дорогами."], "correct": 3, "expl": "Символ розвилки (не перехрестя) з однаково товстими лініями обох напрямків означає рівнозначність доріг розгалуження.", "explSpecific": "Правильно — «Впереди развилка с равнозначными дорогами». «Другорядні дороги» і «двосторонній рух» описують інші деталі символу; «просто другорядна дорога» не передає саме розгалуження на два напрямки.", "img": "q52.png"}, {"num": 53, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди Т-образный перекресток с главной дорогой.", "Впереди перекресток с главной дорогой.", "Впереди перекресток с дорогой с двухсторонним движением.", "Впереди дорога, проходящая под мостом."], "correct": 1, "expl": "Знак перехрестя, де товщина ліній на піктограмі показує, яка дорога головна: якщо ваша лінія товща — ви на головній дорозі.", "explSpecific": "Правильно — «Впереди перекресток с главной дорогой» (ваш напрямок — товща лінія символу). Уточнення «Т-образный» в іншому варіанті не відповідає формі символу на цьому знаку (звичайний хрестоподібний перехрестя, не Т-подібний); «двосторонній рух» і «дорога під мостом» — геть інші символи.", "img": "q53.png"}, {"num": 54, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди Т-образный перекресток со второстепенной дорогой.", "Тупик с обеих сторон.", "Тупик справа.", "Впереди Т-образный перекресток с главной дорогой."], "correct": 3, "expl": "Т-подібний символ перехрестя з потовщеною лінією вашого напрямку означає, що саме ви рухаєтесь головною дорогою.", "explSpecific": "Правильно — «Впереди Т-образный перекресток с главной дорогой». «Другорядна дорога» переплутує, яка лінія товща; «тупик з обох боків» і «тупик справа» описують геть інший символ (літера T з перекладиною, а не перехрестя).", "img": "q54.png"}, {"num": 55, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди Т-образный перекресток.", "Впереди железнодорожный переезд.", "Впереди перекресток с дорогой с двухсторонним движением.", "Впереди неохраняемый железнодорожный переезд."], "correct": 2, "expl": "Трикутний знак перехрестя, де одна з ліній зображена подвійною, означає, що дорога, яка перетинається з вашою, є двосмуговою чи дорогою з двостороннім рухом по кожному боці.", "explSpecific": "Правильно — «Впереди перекресток с дорогой с двухсторонним движением» (горизонтальна лінія на символі подвійна). «Т-подібний перехрестя» описує геть іншу форму символу (без бічного продовження); «залізничний переїзд» і «неохоронюваний переїзд» стосуються geть іншої категорії знаків із символом рейок, а не подвійної лінії дороги.", "img": "q55.png"}, {"num": 56, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди неохраняемый железнодорожный переезд.", "Впереди охраняемый железнодорожный переезд.", "Впереди низкий мост.", "Впереди Т-образный перекресток с дорогой с двухсторонним движением."], "correct": 3, "expl": "Той самий принцип подвійної лінії, що позначає двосторонню дорогу, застосований до Т-подібного перехрестя.", "explSpecific": "Правильно — «Впереди Т-образный перекресток с дорогой с двухсторонним движением» (подвійна лінія зверху символу). «Неохоронюваний» і «охоронюваний залізничний переїзд» стосуються geть іншої категорії знаків (символ рейок); «низький міст» — geть інший за темою символ.", "img": "q56.png"}, {"num": 57, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Конец дороги с двусторонним движением.", "Автомобильный поток слева.", "Автомобильный поток справа.", "Приоритет транспорта, движущегося слева."], "correct": 1, "expl": "Трикутний знак зі стрілкою злиття показує, з якого боку приєднується додатковий потік транспорту.", "explSpecific": "Правильно — «Автомобильный поток слева» (стрілка приєднання зліва). «Кінець двостороннього руху» описує інший символ; «потік справа» переплутує бік; «пріоритет транспорту зліва» додає наказ пріоритету, якого немає на попереджувальному знаку злиття.", "img": "q57.png"}, {"num": 58, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди слияние/разделение движения транспорта.", "Разделения на развязке впереди.", "Впереди резкое сужение дороги.", "Уступите дорогу транспортным потокам, въезжающим и выезжающим на/с главной дороги."], "correct": 0, "expl": "Знак злиття/розділення потоків попереджає про ділянку, де смуги руху сходяться чи розходяться, без наказу пріоритету.", "explSpecific": "Правильно — «Впереди слияние/разделение движения транспорта». «Розділення на розв'язці» і «різке звуження» описують інші, більш специфічні символи; «поступіться дорогою потокам головної дороги» додає наказ, якого немає на суто попереджувальному знаку.", "img": "q58.png"}, {"num": 59, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди улица с односторонним движением.", "Разворот запрещен.", "Впереди кольцевая дорога.", "Впереди перекресток с круговым движением."], "correct": 3, "expl": "Круглий знак-стрілка, що закручується по колу, позначає кільцеву розв'язку попереду.", "explSpecific": "Правильно — «Впереди перекресток с круговым движением». «Одностороння вулиця» і «заборона розвороту» описують геть інші символи; «кільцева дорога» неточно передає саме перехрестя з круговим рухом як окремий тип дороги.", "img": "q59.png"}, {"num": 60, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди скользкая дорога.", "Впереди опасные повороты.", "Впереди ведутся дорожные работы, используйте объезд.", "Впереди кольцевое пересечение."], "correct": 3, "expl": "Знак із трьома вигнутими стрілками, що обертаються навколо центральної точки, — стандартний символ кільцевої розв'язки (перехрестя з круговим рухом) попереду.", "explSpecific": "Правильно — «Впереди кольцевое пересечение». «Ведуться дорожні роботи, об'їзд» і «слизька дорога» позначаються geть іншими символами (силует робітника чи авто в заносі); «небезпечні повороти» — це послідовні S-подібні стрілки, а не коло зі стрілками навколо центру.", "img": "q60.png"}, {"num": 61, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Перекресток слева.", "Впереди улица с односторонним движением.", "Впереди опасный поворот.", "Впереди опасный изгиб дороги."], "correct": 2, "expl": "Кутова стрілка з чітким переломом (майже прямий кут) на попереджувальному знаку позначає саме різкий, небезпечний поворот дороги, на відміну від плавнішого «вигину», який зображують хвилястою лінією.", "explSpecific": "Правильно — «Впереди опасный поворот» (кутова, а не хвиляста стрілка). «Перехрестя зліва» і «одностороння вулиця» описують geть інші символи; «небезпечний вигин дороги» позначається плавнішою, хвилястою лінією — інший, м'якший символ, ніж на цьому знаку.", "img": "q61.png"}, {"num": 62, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Поворот налево.", "Впереди опасный поворот.", "Впереди опасный изгиб дороги.", "Поворот налево запрещен."], "correct": 2, "expl": "Той самий тип знаку вигину дороги, форма стрілки на піктограмі визначає, наскільки плавний чи різкий вигин.", "explSpecific": "Правильно — «Впереди опасный изгиб дороги». «Поворот налево» і «поворот запрещен» переплутують попереджувальний знак із наказовим чи заборонним; «просто небезпечний поворот» позначає різкіший кут на іншому знаку.", "img": "q62.png"}, {"num": 63, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Ряд опасных поворотов впереди.", "Ряд опасных изгибов дороги впереди.", "Линии воздушных электропередач.", "Впереди скользкая дорога."], "correct": 0, "expl": "Знак із кількома послідовними вигинами стрілки попереджає про ряд небезпечних поворотів попереду, а не про один.", "explSpecific": "Правильно — «Ряд опасных поворотов впереди». «Ряд вигинів дороги» описує плавніші зміни напрямку іншим символом; «лінії електропередач» і «слизька дорога» — геть інші попереджувальні символи.", "img": "q63.png"}, {"num": 64, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди крутой подъем.", "Впереди скользкая дорога.", "Ряд опасных поворотов впереди.", "Ряд опасных изгибов дороги впереди."], "correct": 3, "expl": "Знак з рядом вигнутих ліній на піктограмі позначає серію плавних вигинів дороги попереду.", "explSpecific": "Правильно — «Ряд опасных изгибов дороги впереди». «Крутий підйом» і «слизька дорога» — геть інші символи (стрілка вгору чи автомобіль на слизькій поверхні); «ряд поворотів» (різкіших) позначається іншим кутом стрілки на суміжному знаку.", "img": "q64.png"}, {"num": 65, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Дорога закрыта- водителям следует развернуться.", "Ряд переходных путей для движения с повышенной скорость.", "Резкое изменение направления движения влево.", "Резкое изменение направления движения вправо."], "correct": 3, "expl": "Знак з різко вигнутою стрілкою (майже під прямим кутом) попереджає про раптову зміну напрямку дороги, а не плавний вигин.", "explSpecific": "Правильно — «Резкое изменение направления движения вправо». «Дорога закрита» і «переходи для руху з підвищеною швидкістю» описують геть інші символи; «вліво» переплутує напрямок різкої зміни.", "img": "q65.png"}, {"num": 66, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Дорога сужается с левой стороны.", "Сливающийся автомобильный поток слева.", "Обгон разрешается только справа.", "Конец дороги с двухсторонним движением."], "correct": 0, "expl": "Знак звуження дороги показує, з якого боку саме звужується проїжджа частина, за формою ліній на піктограмі.", "explSpecific": "Правильно — «Дорога сужается с левой стороны». «Потік, що зливається зліва» описує інший символ (стрілка приєднання, а не звуження лінії дороги); «обгін лише справа» і «кінець двостороннього руху» не мають стосунку до звуження проїжджої частини.", "img": "q66.png"}, {"num": 67, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди проезжая часть с двусторонним движением.", "Конец дороги с двухсторонним движением.", "Дорога сужается с обеих сторон.", "Впереди туннель."], "correct": 2, "expl": "Знак звуження дороги з обох боків одразу показує симетричне звуження проїжджої частини.", "explSpecific": "Правильно — «Дорога сужается с обеих сторон». «Проїжджа частина з двостороннім рухом попереду» і «кінець такої частини» описують інший символ (роздільна смуга); «тунель» — геть інша піктограма.", "img": "q67.png"}, {"num": 68, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди трамвайная линия.", "Впереди железнодорожный тоннель.", "Обгон только слева.", "Впереди раздельные дороги."], "correct": 3, "expl": "Знак з символом роздільної смуги, що закінчується, позначає місце, де дорога переходить у звичайну двосторонню без розділення.", "explSpecific": "Правильно — «Впереди раздельные дороги» (символ показує початок розділення, а не його кінець чи інший об'єкт). «Трамвайна лінія» і «залізничний тунель» — геть інші піктограми; «обгін лише зліва» не відповідає символу проїзної частини.", "img": "q68.png"}, {"num": 69, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Конец проезжей части с двусторонним движением.", "Впереди сужение дороги.", "Приоритет встречного движения.", "Впереди туннель."], "correct": 0, "expl": "Знак кінця розділеної проїжджої частини показує, де закінчується фізичний розділювач і смуги знову зливаються в звичайну двосторонню дорогу.", "explSpecific": "Правильно — «Конец проезжей части с двусторонним движением» у сенсі закінчення розділеної ділянки. «Звуження дороги» і «пріоритет зустрічного руху» описують геть інші символи; «тунель» — окрема піктограма.", "img": "q69.png"}, {"num": 70, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди улица с односторонним движением.", "Впереди проезжая часть с двусторонним движением.", "Остановка движения запрещена.", "Впереди двустороннее движение."], "correct": 3, "expl": "Знак «Впереди двустороннее движение» попереджає про перехід з розділеної чи односторонньої дороги на звичайну двосторонню ділянку.", "explSpecific": "Правильно — «Впереди двустороннее движение». «Одностороння вулиця попереду» і «проїжджа частина з двостороннім рухом попереду» (як окремий варіант) описують суміжні, але візуально інші символи; «зупинка руху заборонена» — геть інша заборонна піктограма.", "img": "q70.png"}, {"num": 71, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди неровная дорога.", "Впереди крутой подъем.", "Впереди река или не огражденная набережная.", "Впереди крутой спуск."], "correct": 3, "expl": "Знак з символом хвилястої лінії вниз позначає крутий спуск дороги попереду.", "explSpecific": "Правильно — «Впереди крутой спуск». «Нерівна дорога» і «крутий підйом» — геть інші за напрямком стрілки символи; «річка чи набережна без огородження» позначається піктограмою води, а не профілю дороги.", "img": "q71.png"}, {"num": 72, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди крутой подъем.", "Впереди арочный мост.", "Впереди крутой спуск.", "Впереди только транспортные средства, едущие вверх по подъему."], "correct": 0, "expl": "Знак з символом хвилястої лінії вгору позначає крутий підйом дороги попереду — дзеркальний до знаку спуску.", "explSpecific": "Правильно — «Впереди крутой подъем». «Арочний міст» і «крутий спуск» — інші за формою чи напрямком символи; «лише ТЗ, що їдуть вгору» вигадує обмеження, якого попереджувальний знак не встановлює.", "img": "q72.png"}, {"num": 73, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Ограниченная масса транспортного средства для указанного участка дороги.", "Впереди низкий мост.", "Сужение дороги впереди- указана максимальная длина транспортного средства.", "Впереди ограниченная ширина дороги."], "correct": 1, "expl": "Трикутний знак з числом висоти й символом рамки над дорогою попереджає про низький міст або інший навісний об'єкт попереду.", "explSpecific": "Правильно — «Впереди низкий мост». «Обмежена маса» і «обмежена ширина» плутають вид обмеження (вертикальний просвіт, а не вагу чи ширину); «звуження зі вказаною довжиною ТЗ» описує геть інший за призначенням знак.", "img": "q73.png"}, {"num": 74, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Вероятность сильных порывов ветра.", "Впереди матча радиосвязи.", "Линии воздушных электропередач.", "Впереди опасные повороты."], "correct": 2, "expl": "Знак з піктограмою прапорця чи щогли ліній електропередач попереджає про низько підвішені дроти над дорогою.", "explSpecific": "Правильно — «Линии воздушных электропередач». «Сильні пориви вітру» і «небезпечні повороти» — геть інші попереджувальні символи; «радіозв'язок» не є стандартною категорією дорожніх знаків.", "img": "q74.png"}, {"num": 75, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Ведутся дорожные работы.", "Впереди железнодорожный переезд без ворот и шлагбаумов.", "Конец участка дорожных работ.", "Впереди железнодорожный переезд с воротами и шлагбаумом."], "correct": 1, "expl": "Знак залізничного переїзду без додаткового символу воріт попереджає про нерегульований шлагбаумом переїзд.", "explSpecific": "Правильно — «Впереди железнодорожный переезд без ворот и шлагбаума». «Дорожні роботи» і «кінець ділянки робіт» — геть інші за призначенням символи; «переїзд з воротами» вимагав би додаткового елемента огородження на піктограмі, якого тут немає.", "img": "q75.png"}, {"num": 76, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Частная территория. Проезд запрещен.", "Движение сельскохозяйственной техники.", "Впереди дорожное ограждения.", "Впереди железнодорожный переезд с воротами и шлагбаумом."], "correct": 3, "expl": "Знак залізничного переїзду з додатковим символом воріт/шлагбаума попереджає про обладнаний огородженням переїзд.", "explSpecific": "Правильно — «Впереди железнодорожный переезд с воротами и шлагбаумом» (піктограма з огородженням). «Приватна територія» і «рух с/г техніки» — геть інші за призначенням знаки; «дорожнє огородження» саме по собі не передає залізничний контекст піктограми.", "img": "q76.png"}, {"num": 77, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди железнодорожный переезд без ворот и шлагбаума.", "Впереди железнодорожная станция.", "Впереди железнодорожный переезд со светофором и шлагбаумами.", "Впереди железнодорожный мост."], "correct": 2, "expl": "Знак залізничного переїзду може додатково включати символ світлофора, що означає світлову сигналізацію на переїзді разом зі шлагбаумами.", "explSpecific": "Правильно — «Впереди железнодорожный переезд со светофором и шлагбаумами». «Без воріт» суперечить наявності символу огородження; «залізнична станція» і «залізничний міст» — геть інші за призначенням об'єкти.", "img": "q77.png"}, {"num": 78, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Водитель должен остановиться, когда загорится красный цвет.", "Приоритет выезжающих автомобилей. Водитель должен остановиться при необходимости.", "Прежде чем продолжить движение, остановитесь и дождитесь зеленого света.", "Водитель должен остановиться, если у вперед едущего автомобиля включены стоп-сигналы."], "correct": 0, "expl": "Сигнал на залізничному переїзді зі світлофором вимагає зупинки саме в момент, коли загориться червоне світло, а не завчасно чи за іншою ознакою.", "explSpecific": "Правильно — «Водитель должен остановиться, когда загорится красный цвет». «Пріоритет виїжджаючих» і «дочекатися зеленого перед продовженням» описують інші, вигадані для цього сигналу умови; «зупинка через стоп-сигнали переднього авто» не має стосунку до сигналізації переїзду.", "img": "q78.png"}, {"num": 79, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди пешеходный переход через дорогу вблизи школы.", "Впереди место для перехода животных.", "Впереди неохраняемый железнодорожный переезд.", "Впереди автоматический железнодорожный переезд."], "correct": 3, "expl": "Знак з піктограмою поїзда та автоматичних воріт позначає автоматичний залізничний переїзд, обладнаний автоматичною сигналізацією без чергового.", "explSpecific": "Правильно — «Впереди автоматический железнодорожный переезд». «Перехід біля школи» і «перехід тварин» — геть інші за темою знаки; «неохоронюваний переїзд» суперечить наявності автоматичної системи на піктограмі.", "img": "q79.png"}, {"num": 80, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди резкий подъем, например арочный мост.", "Направление дороге от центра влево и вправо.", "Впереди островок безопасности.", "Впереди участок дороги с буграми и выбоинами."], "correct": 0, "expl": "Знак з символом випуклого профілю дороги (як місток чи гребля) попереджає про різку зміну висоти проїзної частини, наприклад аркоподібний міст.", "explSpecific": "Правильно — «Впереди резкий подъем, например арочный мост». «Напрямок дороги від центру» і «острівець безпеки» — геть інші символи; «бугри і виямки» позначаються окремим знаком дрібніших нерівностей, а не одного різкого підйому.", "img": "q80.png"}, {"num": 81, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди дорога повреждена.", "Дорога впереди разделена.", "Впереди глубокая впадина или выбоина.", "Впереди дорога затоплена."], "correct": 2, "expl": "Знак з символом ями чи провалля попереджає про глибоку виямку чи заглиблення проїзної частини попереду.", "explSpecific": "Правильно — «Впереди глубокая впадина или выбоина». «Дорога пошкоджена» і «дорога розділена» — розмиті чи інші за формою піктограми; «дорога затоплена» позначається символом хвиль води, а не ями.", "img": "q81.png"}, {"num": 82, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди предохранительные полосы.", "Ведутся дорожные работы.", "Впереди участок дороги с буграми и выбоинами.", "Впереди крутые холмы."], "correct": 2, "expl": "Знак із рядом горбів на піктограмі попереджає про ділянку дороги з нерівностями — буграми й виямками поспіль.", "explSpecific": "Правильно — «Впереди участок дороги с буграми и выбоинами». «Запобіжні смуги» і «дорожні роботи» — геть інші за призначенням символи; «круті горби» позначає інший, стрімкіший профіль дороги.", "img": "q82.png"}, {"num": 83, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Дорога сужается справа.", "Впереди скользкая дорога.", "Впереди крутой холм.", "Впереди ряд опасных изгибов дороги."], "correct": 1, "expl": "Знак з символом машини, що заносить на слизькій поверхні, попереджає саме про низьке зчеплення з дорогою.", "explSpecific": "Правильно — «Впереди скользкая дорога». «Звужується справа» і «ряд вигинів» — геть інші символи (стрілки чи лінії дороги, не силует авто в заносі); «крутий пагорб» стосується профілю дороги, а не зчеплення.", "img": "q83.png"}, {"num": 84, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди скользкая дорога.", "Дорога подвержена затоплению.", "Впереди крутой спуск.", "Впереди набережная, канал или река. Без ограждения."], "correct": 3, "expl": "Знак з символом хвиль і берега без огородження попереджає про річку, канал чи набережну поруч із дорогою без бар'єру.", "explSpecific": "Правильно — «Впереди набережная, канал или река без ограждения». «Слизька дорога» і «крутий спуск» — геть інші попереджувальні символи; «схильна до затоплення» позначається іншим символом (вода на самій дорозі, а не збоку).", "img": "q84.png"}, {"num": 85, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди железнодорожный переезд.", "Остановитесь у пешеходного перехода с разметкой “зебра”.", "Впереди пешеходный переход через дорогу вблизи школы.", "Впереди светофор."], "correct": 3, "expl": "Трикутний знак із символом трьох кольорових кіл попереджає про світлофор попереду, зазвичай там, де він неочікуваний.", "explSpecific": "Правильно — «Впереди светофор». «Залізничний переїзд» і «зебра» позначаються геть іншими символами; «школа» не має стосунку до символу трьох кіл світлофора.", "img": "q85.png"}, {"num": 86, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди ипподром.", "Конная дорожка-проезд транспорта запрещен.", "Въезд в школу верховой езды.", "Впереди возможность появления всадников на лошадях."], "correct": 3, "expl": "Знак з силуетом коня і вершника попереджає про можливу появу вершників на дорозі попереду.", "explSpecific": "Правильно — «Впереди возможность появления всадников на лошадях». «Іподром» і «школа верхової їзди» вигадують конкретні заклади, яких символ не позначає; «кінна доріжка — проїзд заборонено» це геть інший, заборонний знак.", "img": "q86.png"}, {"num": 87, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди решетчатое ограждение.", "Впереди ветеринарная клиника.", "Вероятность появления скота.", "Вероятность появления крупного рогатого скота или сельскохозяйственных животных."], "correct": 3, "expl": "Знак з силуетом корови попереджає про можливу появу великої рогатої худоби чи іншої сільськогосподарської тварини на дорозі.", "explSpecific": "Правильно — «Вероятность появления крупного рогатого скота или сельскохозяйственных животных». «Ґратчасте огородження» і «ветклініка» — вигадані об'єкти, не пов'язані з силуетом тварини; «просто скот» — менш точне узагальнення порівняно з повним правильним варіантом.", "img": "q87.png"}, {"num": 88, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди скотобойня.", "Проход животных запрещен.", "Вероятность появления овец.", "Впереди овечий рынок."], "correct": 2, "expl": "Знак із силуетом вівці попереджає саме про появу овець на дорозі, на відміну від загального силуету великої рогатої худоби.", "explSpecific": "Правильно — «Вероятность появления овец». «Скотобійня» і «овечий ринок» вигадують конкретні заклади; «заборона проходу тварин» — геть інший, заборонний знак.", "img": "q88.png"}, {"num": 89, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Охота запрещена.", "Впереди ведется охота на оленей.", "Вероятность появления оленей или других диких животных впереди.", "Заповедник. Остановка запрещена."], "correct": 2, "expl": "Знак із силуетом оленя попереджає про можливу появу диких тварин на дорозі, типово в лісистій місцевості.", "explSpecific": "Правильно — «Вероятность появления оленей или других диких животных впереди». «Полювання заборонено» і «ведеться полювання» вигадують діяльність, не позначену символом; «заповідник, зупинка заборонена» — це геть інша заборонна табличка.", "img": "q89.png"}, {"num": 90, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Остерегайтесь пешеходов в ночное время.", "Впереди школа.", "Впереди пешеходный переход.", "Дорожка для пешеходов."], "correct": 2, "expl": "Знак із силуетами дорослого й дитини, що переходять, позначає пішохідний перехід попереду поза зоною школи.", "explSpecific": "Правильно — «Впереди пешеходный переход». «Остерігайтесь пішоходів вночі» і «доріжка для пішоходів» — це варіанти з умовами чи призначенням, яких символ не містить; «школа» позначається окремим знаком із портфелем чи іншим силуетом.", "img": "q90.png"}, {"num": 91, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди детская игровая площадка.", "Впереди пешеходный переход.", "Впереди школа.", "Впереди площадка для пикника."], "correct": 2, "expl": "Знак із силуетами дітей, що переходять дорогу, попереджає про школу поруч і ймовірність появи дітей на проїзній частині.", "explSpecific": "Правильно — «Впереди школа». «Ігровий майданчик» і «місце для пікніка» вигадують інше призначення території; «пішохідний перехід» без шкільного контексту позначається іншим, простішим символом дорослого пішохода.", "img": "q91.png"}, {"num": 92, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди игровая площадка.", "Впереди железнодорожный переезд с пешеходным переходом.", "Впереди пешеходный переход через дорогу вблизи школы.", "Впереди площадка для пикника."], "correct": 2, "expl": "Комбінований знак дітей і пішохідного переходу позначає саме перехід дороги біля школи, а не школу як таку окремо.", "explSpecific": "Правильно — «Впереди пешеходный переход через дорогу вблизи школы». «Ігровий майданчик» і «місце для пікніка» — вигадані призначення; «залізничний переїзд з пішохідним переходом» додає залізницю, якої немає на символі.", "img": "q92.png"}, {"num": 93, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди участок дороги с выбросом гравия.", "Будьте осторожны, дети переходят дорогу", "Скользкая дорога-существует вероятность падения детей.", "Уступите дорогу бегунам."], "correct": 1, "expl": "Знак «Будьте обережні, діти переходять дорогу» — це попередження про підвищену ймовірність раптової появи дітей саме в цьому місці, часто поза офіційним переходом.", "explSpecific": "Правильно — «Будьте осторожны, дети переходят дорогу». «Розсипаний гравій» і «слизько, діти можуть впасти» вигадують інші причини небезпеки; «поступіться дорогою бігунам» стосується геть іншої категорії учасників руху.", "img": "q93.png"}, {"num": 94, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди участок дороги с падающими камнями.", "Впереди поле для гольфа.", "Вероятность сильных порывов ветра.", "Впереди аэропорт."], "correct": 2, "expl": "Знак із силуетом прапорця-конуса (вітрового рукава) попереджає про ймовірність сильних поривів бічного вітру, типово на відкритих ділянках чи мостах.", "explSpecific": "Правильно — «Вероятность сильных порывов ветра». «Падаючі камені» і «поле для гольфа» — геть інші за темою символи; «аеропорт» не позначається символом вітрового рукава окремо від контексту летовища.", "img": "q94.png"}, {"num": 95, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди низкий мост.", "Впереди собор или церковь.", "Впереди историческая достопримечательность.", "Впереди туннель."], "correct": 3, "expl": "Знак із симетричною аркою і цеглинками по контуру — стандартний символ тунелю попереду, а не пам'ятки чи споруди.", "explSpecific": "Правильно — «Впереди туннель». «Низький міст» позначається geть іншим символом (горизонтальна рамка над дорогою); «історична пам'ятка» і «собор чи церква» — вигадані для цього символу об'єкти, які не мають стосунку до арки тунелю.", "img": "q95.png"}, {"num": 96, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Участок дороги с вероятностью падения листьев.", "Вероятность падения камней.", "Впереди скалистый берег.", "Впереди крутой спуск."], "correct": 1, "expl": "Знак із силуетом дерева і крапок, що падають, попереджає про ймовірність падіння каміння чи природних об'єктів на дорогу, типово біля скельних укосів.", "explSpecific": "Правильно — «Вероятность падения камней». «Ділянка з падаючим листям» вигадує сезонну причину, якої символ не уточнює; «скелястий берег» і «крутий спуск» стосуються профілю місцевості, а не падаючих об'єктів.", "img": "q96.png"}, {"num": 97, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди аэропорт.", "Вероятность низколетящего самолета.", "Впереди музей авиации.", "Направление преобладающего ветра."], "correct": 1, "expl": "Знак із силуетом літака попереджає про ймовірність низько летючого повітряного судна поблизу аеропорту.", "explSpecific": "Правильно — «Вероятность низколетящего самолета». «Аеропорт» без уточнення про політ — менш точне узагальнення; «музей авіації» і «напрямок вітру» вигадують інше призначення символу літака.", "img": "q97.png"}, {"num": 98, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Обгон разрешается только слева.", "Разрешается ехать только по левой стороне дороги.", "Водитель должен уступать дорогу транспорту на правой стороне дороги.", "Парковка разрешена слева."], "correct": 1, "expl": "Знак «Drive on left / Conduire à gauche / Links fahren» — це нагадування для водіїв, які звикли до правостороннього руху, що в Ірландії потрібно триматися лівої сторони дороги.", "explSpecific": "Правильно — «Разрешается ехать только по левой стороне дороги» (сенс тут не «дозволено», а «зобов'язані», що передає той самий загальний зміст найточніше серед варіантів). «Обгін лише зліва» і «парковка дозволена зліва» звужують загальне правило до конкретних маневрів, яких символ не уточнює; варіант про поступання дорогою праворуч суперечить самій суті нагадування — їхати лівою стороною.", "img": "q98.png"}, {"num": 99, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди железнодорожный переезд.", "Впереди переезд для автобусов и пересечение трамвайных путей.", "Впереди пересечение трамвайных путей.", "Впереди железнодорожная станция."], "correct": 2, "expl": "Знак із символом трамвайних рейок, що перетинають дорогу, попереджає про перетин трамвайних колій попереду.", "explSpecific": "Правильно — «Впереди пересечение трамвайных путей». «Залізничний переїзд» переплутує трамвай із поїздом (інша піктограма); «переїзд для автобусів і трамваїв» додає автобуси, яких немає на символі; «залізнична станція» — геть інший об'єкт.", "img": "q99.png"}, {"num": 100, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди железнодорожный переезд.", "Впереди переезд для автобусов и пересечение трамвайных путей.", "Впереди пересечение трамвайных путей.", "Впереди железнодорожная станция."], "correct": 2, "expl": "Той самий знак перетину трамвайних колій може повторюватись на дорозі кілька разів перед складним перехрестям з трамваями.", "explSpecific": "Правильно — «Впереди пересечение трамвайных путей», з тих самих причин: символ показує лише рейки, без потяга чи автобуса. Інші варіанти додають об'єкти чи заклади, яких немає на піктограмі.", "img": "q100.png"}, {"num": 101, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди велосипедная дорожка.", "Впереди трамвайные пути, велосипедистам следует проявить осторожность.", "Впереди велосипедная дорожка и трамвайные пути.", "Трамваи могут закрывать обзор велосипедистам."], "correct": 1, "expl": "Комбінований знак велосипеда й трамвайних рейок попереджає велосипедистів про потребу особливої обережності саме через ризик застрягання колеса в рейковій колії.", "explSpecific": "Правильно — «Впереди трамвайные пути, велосипедистам следует проявить осторожность». Просто «велосипедна доріжка» ігнорує символ рейок; «велодоріжка і трамвайні колії» неточно поєднує два окремі елементи символу як один об'єкт; «трамваї можуть закривати огляд» вигадує причину, не пов'язану з піктограмою колії.", "img": "q101.png"}, {"num": 102, "text": "Какому виду транспорта этот знак не запрещает находиться на автомагистрали?", "topic": "Дорожні знаки та розмітка", "options": ["Транспортным средствам с домами для кемпинга.", "Сельскохозяйственный транспорт.", "Мотоциклы.", "Грузовики с прицепами."], "correct": 0, "expl": "Знак заборони на автомагістралі перекреслює силуети пішоходів, велосипедистів, тихохідного та сільськогосподарського транспорту — але не звичайні легкові автомобілі з причепом-караваном для житла.", "explSpecific": "Правильно — «Транспортным средствам с домами для кемпинга» (караван, що тягнеться легковим автомобілем, дозволений на автомагістралі). Сільгосптехніка, мотоцикли (в Ірландії дозволені, але тут малися на увазі мопеди/малокубатурні) та вантажівки з причепами в цьому переліку заборонених категорій фігурують як заборонені, тоді як побутовий караван — ні.", "img": "q102.png"}, {"num": 103, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Конец автомагистрали.", "Впереди платный мост.", "Впереди низкий мост.", "Въезд на автомагистрали."], "correct": 3, "expl": "Синій прямокутний знак з трьома смугами та назвою дороги позначає початок автомагістралі — в'їзд на неї.", "explSpecific": "Правильно — «Въезд на автомагистрали». «Кінець автомагістралі» позначається перекресленим варіантом того самого символу; «платний» і «низький міст» — геть інші за темою знаки, не пов'язані з початком автомагістралі.", "img": "q103.png"}, {"num": 104, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Обгон запрещен на участке в 500 метров.", "Через 500 метров ремонтируемый мост.", "До конца автомагистрали 500 метров.", "Через 500 метров низкий мост."], "correct": 2, "expl": "Синя табличка з перекресленим символом автомагістралі та числом метрів під нею повідомляє відстань до кінця ділянки автомагістралі.", "explSpecific": "Правильно — «До конца автомагистрали 500 метров» (перекреслений символ автомагістралі = кінець). «Заборона обгону на ділянці» і «міст через 500 метрів» (у ремонті чи низький) вигадують geть інший об'єкт основного знаку, який на піктограмі не показаний.", "img": "q104.png"}, {"num": 105, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Стоянка не более, чем для трех автомобилей.", "До следующего съезда 300 метров.", "Впереди выезд на полосу встречного движения.", "Впереди трехполосная дорога."], "correct": 1, "expl": "Табличка з відстанню на автомагістралі зазвичай відраховує метри до наступного з'їзду, допомагаючи водію завчасно перешикуватися.", "explSpecific": "Правильно — «До следующего съезда 300 метров». «Стоянка не більше трьох авто» і «трисмугова дорога» вигадують геть інший зміст числа «3»; «виїзд на смугу зустрічного руху» не відповідає типовому контексту такої таблички на автомагістралі.", "img": "q105.png"}, {"num": 106, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди пересечение с дорогой с двусторонним движением.", "Обгон запрещен на участке в 200 метров.", "Резкий спуск через 200 метров.", "До следующего съезда 200 метров."], "correct": 3, "expl": "Аналогічна табличка відраховує метри до наступного з'їзду з автомагістралі.", "explSpecific": "Правильно — «До следующего съезда 200 метров». «Перетин з двостороннім рухом», «заборона обгону» і «різкий спуск» приписують числу «200» геть інший, невідповідний контекстові автомагістралі зміст.", "img": "q106.png"}, {"num": 107, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["До следующего съезда 100 метров.", "Впереди низкий мост.", "100 метров участок резкого спуска.", "Крутой подъем через 100 метров."], "correct": 0, "expl": "Та сама серія таблиць відліку відстані до з'їзду, зазвичай встановлюються серіями (300-200-100 метрів).", "explSpecific": "Правильно — «До следующего съезда 100 метров», завершуючи серію попередніх таблиць. «Низький міст», «різкий спуск» і «крутий підйом» не відповідають типовому призначенню таких послідовних лічильників відстані.", "img": "q107.png"}, {"num": 108, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди не мостов.", "Конец участка дороги с надземными мостами.", "Обгон запрещен.", "Конец автомагистрали."], "correct": 3, "expl": "Перекреслений символ автомагістралі позначає саме кінець ділянки з режимом автомагістралі, після чого діють звичайні правила дороги.", "explSpecific": "Правильно — «Конец автомагистрали». «Немає мостів» і «кінець ділянки з надземними мостами» вигадують об'єкти, не пов'язані з перекресленим символом автомагістралі; «заборона обгону» — геть інший, заборонний знак.", "img": "q108.png"}, {"num": 109, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Полоса с пунктом сбора дорожной пошлины.", "Полицейский участок слева.", "Впереди станция технического обслуживания.", "Эта полоса закрыта-держитесь левой стороны."], "correct": 0, "expl": "Знак над смугою на в'їзді до пункту оплати проїзду позначає призначення саме цієї смуги — збір дорожньої пошлини.", "explSpecific": "Правильно — «Полоса с пунктом сбора дорожной пошлины». «Поліцейська дільниця» і «станція техобслуговування» — geть інші об'єкти; «смуга закрита» суперечить дозвільному, а не забороняючому характеру знаку над відкритою смугою.", "img": "q109.png"}, {"num": 110, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Касса на этой полосе.", "Корзина для монет на этой полосе.", "Билетный автомат на этой полосе.", "Система автоматического сбора пошлины."], "correct": 1, "expl": "Піктограма монети над смугою оплати означає, що на цій смузі приймають готівку монетами в спеціальну корзину чи автомат.", "explSpecific": "Правильно — «Корзина для монет на этой полосе». «Каса» і «білетний автомат» описують інші за виглядом пристрої; «система автоматичного збору пошлини» стосується електронного, а не готівкового способу оплати з піктограмою монети.", "img": "q110.png"}, {"num": 111, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Электронный платеж не взимается на этой полосе.", "Электронный платеж взимается на любой полосе.", "Оплата в евро на этой полосе.", "Электронный платеж вне очереди на этой полосе."], "correct": 3, "expl": "Знак над смугою може позначати спеціальну смугу для електронної оплати (наприклад, транспондер), що дозволяє проїзд без зупинки, часто окремо від черги.", "explSpecific": "Правильно — «Электронный платеж вне очереди на этой полосе». «Не стягується» і «стягується на будь-якій» суперечать призначенню виділеної смуги; «оплата в євро» не стосується суті електронного способу оплати.", "img": "q111.png"}, {"num": 112, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди посадка деревьев.", "Впереди строительная площадка.", "Впереди ведутся дорожные работы.", "Впереди грязевой поток."], "correct": 2, "expl": "Знак з силуетом робітника й лопати позначає ділянку, де ведуться дорожні роботи.", "explSpecific": "Правильно — «Впереди ведутся дорожные работы». «Посадка дерев» і «грязьовий потік» — вигадані причини, не пов'язані з силуетом робітника; «будівельний майданчик» — занадто загальне й не специфічне для дороги формулювання.", "img": "q112.png"}, {"num": 113, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди неровная дорога.", "Впереди крутые холмы.", "Впереди промышленный объект.", "Впереди ведется прокладка труб."], "correct": 0, "expl": "Знак із хвилястою лінією посередині ромба попереджає про нерівну поверхню проїзної частини попереду.", "explSpecific": "Правильно — «Впереди неровная дорога». «Круті пагорби» і «прокладання труб» — геть інші за темою символи; «промисловий об'єкт» не має стандартного дорожнього символу такого вигляду.", "img": "q113.png"}, {"num": 114, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Скользкий участок.", "Впереди крутой холм.", "Впереди ряд опасных изгибов дороги.", "Дорога сужается справа."], "correct": 0, "expl": "Знак із силуетом автомобіля, що заносить, на глянцевій поверхні позначає слизьку ділянку дороги.", "explSpecific": "Правильно — «Скользкий участок». «Крутий пагорб» і «ряд вигинів» — інші за формою символи (профіль чи лінія дороги, а не занос авто); «звужується справа» стосується ширини, а не зчеплення з дорогою.", "img": "q114.png"}, {"num": 115, "text": "что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Дорога сужается слева.", "Конец полосы медленного движения.", "Неровная поверхность левой полосы движения.", "Обгон разрешается только справа"], "correct": 0, "expl": "Знак звуження зі стрілкою, що йде зліва, позначає зникнення лівої смуги руху попереду.", "explSpecific": "Правильно — «Дорога сужается слева». «Кінець смуги повільного руху» і «нерівна поверхня лівої смуги» вигадують інший тип змін дорожнього покриття; «обгін лише справа» — заборонний знак геть іншого вигляду.", "img": "q115.png"}, {"num": 116, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Обгон разрешается только справа.", "Дорога сужается справа.", "Конец полосы обгона.", "Неровная поверхность правой полосы движения."], "correct": 1, "expl": "Дзеркальний знак звуження показує зникнення саме правої смуги руху попереду.", "explSpecific": "Правильно — «Дорога сужается справа». «Обгін лише справа» — заборонний знак іншого вигляду; «кінець смуги обгону» і «нерівна поверхня правої смуги» вигадують інший тип зміни дороги, не пов'язаний зі звуженням.", "img": "q116.png"}, {"num": 117, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Конец препятствий между полосами движения.", "Слияние автомобильных потоков обеих сторон.", "Дорога сужается с обеих сторон.", "Конец дороги с двухсторонним движением."], "correct": 2, "expl": "Знак із двома стрілками, що сходяться з обох боків, позначає звуження проїзної частини одночасно зліва й справа.", "explSpecific": "Правильно — «Дорога сужается с обеих сторон». «Кінець перешкод між смугами» і «злиття потоків з обох боків» описують інші за формою символи (роздільник чи потоки, не звуження країв); «кінець двостороннього руху» — геть інша піктограма.", "img": "q117.png"}, {"num": 118, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Путешествие автостопом разрешено.", "Пешеходный переход справа.", "Впереди футбольный стадион.", "Впереди регулировщик."], "correct": 3, "expl": "Знак із силуетом людини, що керує рухом, попереджає про регулювальника на дорозі попереду, чиї сигнали мають пріоритет над іншими знаками й світлофорами.", "explSpecific": "Правильно — «Впереди регулировщик». «Автостоп дозволено» і «футбольний стадіон» — вигадані, не пов'язані з силуетом регулювальника; «пішохідний перехід справа» позначається геть іншим символом.", "img": "q118.png"}, {"num": 119, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди временное дорожное покрытие.", "Впереди временный светофор.", "Впереди пешеходный переход через дорогу вблизи школы.", "Впереди железнодорожный переезд."], "correct": 1, "expl": "Знак світлофора з додатковою міткою «тимчасовий» попереджає про світлофор, встановлений тимчасово, наприклад на період дорожніх робіт.", "explSpecific": "Правильно — «Впереди временный светофор». «Тимчасове дорожнє покриття» і «залізничний переїзд» — geть інші за темою символи; «перехід біля школи» не пов'язаний із символом світлофора.", "img": "q119.png"}, {"num": 120, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Остановка движения запрещена.", "Впереди проезжая часть с двусторонним движением.", "Улица с односторонним движением.", "Двустороннее движение."], "correct": 3, "expl": "Знак, що показує дві протилежні стрілки поруч, позначає ділянку звичайного двостороннього руху після розділеної чи односторонньої дороги.", "explSpecific": "Правильно — «Двустороннее движение». «Зупинка руху заборонена» — геть інший заборонний символ; «проїжджа частина з двостороннім рухом попереду» описує суміжний, але окремий знак попередження, а не факт початку такого руху; «одностороння вулиця» суперечить самій суті двох протилежних стрілок.", "img": "q120.png"}, {"num": 121, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Транспорт на ближайшей полосе движения должен повернуть налево.", "Левая полоса движения из двух закрыта.", "Т-образный перекресток впереди на левой полосе движения.", "Правая полоса движения из двух закрыта."], "correct": 1, "expl": "Знак закриття смуги на автомагістралі чи багатосмуговій дорозі показує стрілкою, яка саме смуга закінчується попереду і водій повинен перешикуватись.", "explSpecific": "Правильно — «Левая полоса движения из двух закрыта» (стрілка зліва обривається). «Транспорт повинен повернути ліворуч» неправильно трактує знак закриття смуги як наказ повороту; «Т-подібний перехрестя» і «права смуга закрита» описують геть інші символи.", "img": "q121.png"}, {"num": 122, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Левая полоса движения из трех закрыта.", "Обгон запрещен на левой полосе.", "Поворот налево запрещен.", "Проезд по краевой полосе запрещен."], "correct": 0, "expl": "Той самий тип знаку закриття смуги, але для дороги з трьома смугами — стрілка лівої смуги переривається.", "explSpecific": "Правильно — «Левая полоса движения из трех закрыта». «Обгін заборонено на лівій» і «поворот ліворуч заборонено» — geть інші заборонні символи; «проїзд по крайовій смузі заборонено» стосується узбіччя, а не внутрішньої смуги руху.", "img": "q122.png"}, {"num": 123, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди участок дороги с выбросом гравия.", "Впереди справа поломанное транспортные средство.", "Наводнение впереди слева.", "Неровный участок слева."], "correct": 0, "expl": "Знак з силуетом камінців чи щебеню попереджає про ділянку, де можливе розкидання гравію з-під коліс.", "explSpecific": "Правильно — «Впереди участок дороги с выбросом гравия». «Поламане ТЗ справа» і «підтоплення зліва» — геть інші за темою попередження; «нерівний ділянка зліва» стосується профілю дороги, а не гравію.", "img": "q123.png"}, {"num": 124, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Правая полоса впереди закрыта.", "Поворот дороги впереди на правой полосе.", "Конец дороги с двусторонним движением.", "Остановка разрешена исключительно на правой стороне."], "correct": 0, "expl": "Знак закриття смуги, дзеркальний до №121 — обривається саме права смуга дороги.", "explSpecific": "Правильно — «Правая полоса впереди закрыта». «Поворот дороги на правій смузі» і «кінець двостороннього руху» — geть інші символи; «зупинка дозволена лише на правій стороні» не пов'язана зі знаком закриття смуги руху.", "img": "q124.png"}, {"num": 125, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Вероятность транспортного затвора впереди.", "Стоянка для рабочего транспорта слева.", "Впереди могут стоять три автомобиля.", "Впереди крутой уклон."], "correct": 0, "expl": "Знак з силуетом черги автомобілів попереджає про ймовірність затору попереду, щоб водій завчасно знизив швидкість.", "explSpecific": "Правильно — «Вероятность транспортного затора впереди». «Стоянка робочого транспорту зліва» і «можуть стояти три автомобілі» вигадують інший сенс силуету машин; «крутий укіс» стосується профілю дороги, а не затору.", "img": "q125.png"}, {"num": 126, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Стоянка разрешена только слева.", "Впереди мягкое ограждение.", "Скользкая поверхность.", "Неровная поверхность."], "correct": 3, "expl": "Знак з хвилястою лінією на поверхні дороги попереджає про нерівну поверхню проїзної частини, на відміну від знаку слизької дороги з силуетом заносу.", "explSpecific": "Правильно — «Неровная поверхность». «Стоянка лише зліва» і «м'яке огородження» — геть інші за темою символи; «слизька поверхня» позначається окремим знаком із силуетом машини в заносі, а не хвилястою лінією.", "img": "q126.png"}, {"num": 127, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди проезжая часть с двусторонним движением.", "Впереди кольцевое пересечение.", "Начало центральной полосы или препятствия.", "Тяжелые транспортные средства имеют приоритет."], "correct": 2, "expl": "Знак з вертикальною стрілкою чи прямокутником по центру дороги позначає початок центральної розділювальної смуги або перешкоди посередині проїзної частини.", "explSpecific": "Правильно — «Начало центральной полосы или препятствия». «Двостороннє попереду» і «кільцеве перехрестя» — geть інші символи; «пріоритет важких ТЗ» вигадує правило, якого немає на цьому попереджувальному знаку.", "img": "q127.png"}, {"num": 128, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Пешеходам проезд запрещен.", "Пешеходы, держитесь середины дороги.", "Пешеходы, держитесь левой стороны.", "Пешеходы, держитесь правой стороны."], "correct": 3, "expl": "Знак із силуетом пішохода і стрілкою вказує, з якого боку дороги пішоходам слід іти за відсутності тротуару.", "explSpecific": "Правильно — «Пешеходы, держитесь правой стороны». «Проїзд заборонено» — геть інший заборонний символ; «середина дороги» і «ліва сторона» переплутують напрямок, вказаний стрілкою на піктограмі.", "img": "q128.png"}, {"num": 129, "text": "Что означает этот знак в местах проведения дорожных работ?", "topic": "Дорожні знаки та розмітка", "options": ["Осторожно продолжайте движение.", "Продолжайте движение только при наличии соответствующего знака.", "Продолжайте движение только с аварийными включенными огнями.", "Продолжайте движение подавая сигналы рукой."], "correct": 0, "expl": "Тимчасовий знак на ділянці дорожніх робіт із загальним попередженням means водій має продовжувати рух обережно, зважаючи на змінені умови.", "explSpecific": "Правильно — «Осторожно продолжайте движение». «Тільки за наявності відповідного знаку» і «тільки з аварійними вогнями» додають умови, яких немає на самому знаку; «сигналізуючи рукою» вигадує дію, не пов'язану із загальним попередженням про обережність.", "img": "q129.png"}, {"num": 130, "text": "Что означает этот знак в местах проведения дорожных работ?", "topic": "Дорожні знаки та розмітка", "options": ["Остановка для директора школы.", "Остановка только в случае встречного движения.", "Остановка перед знаком или на нем.", "Продолжайте движение, если дорога впереди свободна."], "correct": 2, "expl": "Тимчасовий знак на ділянці робіт може вимагати зупинки саме перед знаком чи на ньому, аналогічно постійному знаку STOP.", "explSpecific": "Правильно — «Остановка перед знаком или на нем». «Зупинка для директора школи» — вигадана, не пов'язана з дорожніми роботами умова; «лише при зустрічному русі» і «продовжуйте якщо вільно» суперечать обов'язковому характеру зупинки на такому знаку.", "img": "q130.png"}, {"num": 131, "text": "Что означают эти знаки вместе?", "topic": "Швидкісний режим", "options": ["Конец дороги.", "Конец участка проведения дорожных работ.", "Конец участка со скоростным ограничением.", "Конец объезда."], "correct": 3, "expl": "Помаранчева табличка «END DETOUR» разом із білою «END» означає закінчення тимчасового об'їзду і всіх пов'язаних з ним тимчасових обмежень.", "explSpecific": "Правильно — «Конец объезда»: напис прямо перекладається як «кінець об'їзду». «Кінець дороги», «кінець дорожніх робіт» і «кінець ділянки зі швидкісним обмеженням» — це підписи для геть інших комбінацій тимчасових знаків, які виглядають інакше.", "img": "q131.png"}, {"num": 132, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Изгиб на дороге впереди слева.", "Впереди полоса медленного движения для тяжелых транспортных средств.", "Транспорт должен перейти на полосу противоположным направлением впереди слева.", "Впереди придорожная площадка для стоянки автотранспорта."], "correct": 2, "expl": "Знак переходу на смугу зустрічного напрямку (типово на ділянці ремонту) показує стрілкою, в який бік і де саме відбувається тимчасове перекриття своєї смуги.", "explSpecific": "Правильно — «Транспорт должен перейти на полосу противоположным направлением впереди слева». «Вигин дороги зліва» і «смуга повільного руху для важких ТЗ» — geть інші за призначенням символи; «майданчик для стоянки» не пов'язаний із тимчасовою зміною смуги руху.", "img": "q132.png"}, {"num": 133, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Транспорт должен перейти на полосу с противоположным направлением впереди справа.", "Впереди участки обеспечения принудительного снижения скорости транспорта.", "Изгиб на дороге впереди справа.", "Конец участка запрета обгона."], "correct": 0, "expl": "Дзеркальний варіант знаку тимчасового переходу на зустрічну смугу — перехід відбувається праворуч.", "explSpecific": "Правильно — «Транспорт должен перейти на полосу с противоположным направлением впереди справа». «Дільниці примусового зниження швидкості» і «вигин дороги справа» — geть інші символи; «кінець заборони обгону» не пов'язаний із тимчасовою зміною смуги руху.", "img": "q133.png"}, {"num": 134, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди проезжая часть с двусторонним движением.", "Впереди кольцевое пересечение.", "Начало центральной разделительной полосы или препятствия.", "Тяжелые транспортные средства имеют приоритет."], "correct": 2, "expl": "Знак початку центральної розділювальної смуги чи перешкоди — той самий тип символу, що й у сусідніх знаках цієї серії.", "explSpecific": "Правильно — «Начало центральной разделительной полосы или препятствия»: символ показує об'єкт посередині дороги, а не тип перехрестя чи правило пріоритету, вигадані в інших варіантах.", "img": "q134.png"}, {"num": 135, "text": "Что означает этот знак?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди конец туннеля.", "Конец центральной разделительной полосы или препятствия.", "Остерегайтесь крупногабаритных транспортных средств.", "Впереди дорога с двусторонним движением."], "correct": 1, "expl": "Знак кінця центральної розділювальної смуги чи перешкоди позначає місце, де закінчується розділення і смуги знову зливаються.", "explSpecific": "Правильно — «Конец центральной разделительной полосы или препятствия». «Кінець тунелю» і «двостороннє попереду» — geть інші за темою символи; «остерігайтесь великогабаритних ТЗ» вигадує попередження, не пов'язане із символом розділювача.", "img": "q135.png"}, {"num": 136, "text": "Что означает этот сигнал, подаваемый рукой?", "topic": "Обгін та зміна смуги руху", "options": ["Велосипедист собирается съехать с полосы или повернуть направо.", "Велосипедист намерен снизить скорость.", "Велосипедист собирается въехать на полосу или повернуть налево.", "Велосипедист намерен остановиться."], "correct": 0, "expl": "Велосипедист, простягаючи руку прямо в сторону, вказує напрямок, куди він збирається повернути або перестроїтися — так само, як і водії, тільки велосипедист використовує саме ту руку, в яку сторону повертає.", "explSpecific": "Правильно — «Велосипедист собирается съехать с полосы или повернуть направо» (права рука витягнута вбік). «Намерен снизить скорость» і «намерен остановиться» позначаються іншим жестом (рука вгору чи рух рукою вниз); «собирается повернуть налево» переплутує бік — це була б витягнута ліва рука.", "img": "q136.png"}, {"num": 137, "text": "Что означает этот сигнал, подаваемый рукой?", "topic": "Обгін та зміна смуги руху", "options": ["Велосипедист сообщает о возможности обгона для следующего за ним транспорта.", "Велосипедист намерен снизить скорость или остановиться.", "Велосипедист намерен снизить скорость.", "Велосипедист намерен повернуть налево."], "correct": 1, "expl": "Рух рукою вниз чи повільне погойдування — стандартний сигнал велосипедиста про намір знизити швидкість або зупинитися, на відміну від нерухомої витягнутої вбік руки, яка вказує напрямок повороту.", "explSpecific": "Правильно — «Велосипедист намерен снизить скорость или остановиться». «Сообщает о возможности обгона» — вигаданий сигнал, якого не існує в стандартному переліку; «намерен снизить скорость» окремо (без зупинки) і «намерен повернуть налево» описують інші, конкретніші чи geть інші жести.", "img": "q137.png"}, {"num": 138, "text": "Что означает этот сигнал, подаваемый рукой?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Велосипедист намерен повернуть налево.", "Велосипедист намерен остановиться.", "Велосипедист намерен ехать прямо.", "Велосипедист уступает дорогу другому транспорту."], "correct": 2, "expl": "Піднята вертикально вгору рука велосипедиста — сигнал «їду прямо», який використовують на перехресті, щоб уникнути помилкового враження, ніби велосипедист повертає.", "explSpecific": "Правильно — «Велосипедист намерен ехать прямо». «Повернуть налево» і «остановиться» позначаються geть іншими жестами (витягнута вбік чи опущена рука); «уступает дорогу другому транспорту» не є стандартним сигналом, що подається рукою.", "img": "q138.png"}, {"num": 139, "text": "Что означает этот сигнал, подаваемый рукой?", "topic": "Обгін та зміна смуги руху", "options": ["Велосипедист намерен остановиться.", "Велосипедист намерен совершить обгон.", "Велосипедист намерен повернуть налево.", "Велосипедист намерен слезть с велосипед."], "correct": 2, "expl": "Велосипедист, на відміну від водія автомобіля в кабіні, може просто витягнути ліву руку прямо вбік, щоб позначити намір повернути ліворуч.", "explSpecific": "Правильно — «Велосипедист намерен повернуть налево» (витягнута ліва рука). «Остановиться» і «совершить обгон» позначаються іншими жестами; «слезть с велосипеда» не є стандартним сигналом руху взагалі.", "img": "q139.png"}, {"num": 140, "text": "Что означает этот сигнал, подаваемый рукой?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Велосипедист намерен остановиться.", "Велосипедист намерен повернуть направо.", "Велосипедист намерен повернуть налево.", "Велосипедист намерен снизить скорость."], "correct": 1, "expl": "Дзеркальний до лівого сигнал — витягнута права рука велосипедиста означає намір повернути праворуч.", "explSpecific": "Правильно — «Велосипедист намерен повернуть направо». «Остановиться» і «повернуть налево» позначаються іншими жестами (відповідно вгору чи лівою рукою); «снизить скорость» — geть інший, повільний рух рукою вниз, а не нерухома витягнута вбік рука.", "img": "q140.png"}, {"num": 141, "text": "Что означает этот сигнал, подаваемый рукой?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Велосипедист намерен пересечь дорогу.", "Велосипедист намерен повернуть налево.", "Велосипедист сообщает водителю о необходимости остановиться.", "Велосипедист намерен остановиться."], "correct": 1, "expl": "Той самий сигнал витягнутої лівої руки, що позначає лівий поворот велосипедиста.", "explSpecific": "Правильно — «Велосипедист намерен повернуть налево». «Пересечь дорогу» і «сообщает водителю о необходимости остановиться» вигадують сигнали, яких не існує в стандартному переліку; «намерен остановиться» позначається іншим жестом (піднята вгору рука).", "img": "q141.png"}, {"num": 142, "text": "Что означает этот сигнал, подаваемый рукой?", "topic": "Швидкісний режим", "options": ["Водитель намерен повернуть направо.", "Водитель намерен ехать прямо.", "Водитель намерен снизить скорость или остановиться.", "Водитель намерен повернуть налево."], "correct": 3, "expl": "Оскільки водій керує з правого боку автомобіля (лівосторонній рух), витягнути ліву руку для сигналу лівого повороту фізично незручно — тому водії позначають лівий поворот круговими обертами правою рукою за вікном.", "explSpecific": "Правильно — «Водитель намерен повернуть налево» (кругові оберти рукою). «Повернуть направо» позначається нерухомою прямою рукою; «ехать прямо» і «снизить скорость/остановиться» позначаються geть іншими жестами (піднята вгору рука чи рух вгору-вниз).", "img": "q142.png"}, {"num": 143, "text": "Что означает этот сигнал, подаваемый рукой?", "topic": "Обгін та зміна смуги руху", "options": ["Водитель собирается съехать с полосы или повернуть направо.", "Водитель намерен остановится.", "Водитель намерен повернуть налево.", "Водитель намерен сделать разворот."], "correct": 0, "expl": "Пряма витягнута вбік рука водія — сигнал наміру повернути праворуч або перестроїтися вправо, найпростіший з усіх водійських сигналів.", "explSpecific": "Правильно — «Водитель собирается съехать с полосы или повернуть направо». «Намерен остановиться» і «сделать разворот» позначаються geть іншими жестами; «повернуть налево» для водія позначається круговими обертами, а не прямою рукою.", "img": "q143.png"}, {"num": 144, "text": "Что означает этот сигнал, подаваемый рукой?", "topic": "Швидкісний режим", "options": ["Водитель намерен повернуть направо.", "Водитель намерен начать разворот.", "Водитель намерен повернуть налево.", "Водитель намерен снизить скорость или остановиться."], "correct": 3, "expl": "Повільний рух витягнутої руки водія вгору-вниз — стандартний сигнал про намір знизити швидкість або зупинитися.", "explSpecific": "Правильно — «Водитель намерен снизить скорость или остановиться». «Повернуть направо» позначається нерухомою прямою рукою; «начать разворот» і «повернуть налево» для водія позначаються круговими обертами руки, а не рухом вгору-вниз.", "img": "q144.png"}, {"num": 145, "text": "Что означает этот сигнал, подаваемый рукой?", "topic": "Швидкісний режим", "options": ["Водитель намерен повернуть налево.", "Водитель намерен повернуть направо.", "Водитель намерен остановиться.", "Водитель намерен снизить скорость."], "correct": 0, "expl": "Кругові оберти рукою водія за вікном — той самий сигнал лівого повороту, що й у попередньому питанні.", "explSpecific": "Правильно — «Водитель намерен повернуть налево» (кругові оберти). «Повернуть направо» позначається нерухомою прямою рукою; «остановиться» і «снизить скорость» позначаються рухом руки вгору-вниз, а не круговими обертами.", "img": "q145.png"}, {"num": 146, "text": "Что означает этот сигнал, подаваемый рукой?", "topic": "Швидкісний режим", "options": ["Водитель намерен снизить скорость.", "Водитель намерен повернуть направо.", "Водитель начинает движения задним ходом.", "Водитель намерен повернуть налево."], "correct": 1, "expl": "Нерухома пряма витягнута вбік рука водія позначає намір повернути праворуч, так само, як і в аналогічного сигналу велосипедиста.", "explSpecific": "Правильно — «Водитель намерен повернуть направо». «Снизить скорость» позначається рухом руки вгору-вниз; «начинает движение задним ходом» не має стандартного сигналу рукою взагалі; «повернуть налево» для водія позначається круговими обертами.", "img": "q146.png"}, {"num": 147, "text": "Что означает этот сигнал, подаваемый рукой?", "topic": "Швидкісний режим", "options": ["Водитель начинает движения задним ходом.", "Водитель намерен ехать прямо.", "Водитель намерен повернуть налево.", "Водитель намерен снизить скорость или остановиться."], "correct": 1, "expl": "Піднята вертикально вгору нерухома рука водія — сигнал «їду прямо», аналогічний до сигналу велосипедиста, що запобігає помилковому враженню про поворот на перехресті.", "explSpecific": "Правильно — «Водитель намерен ехать прямо». «Начинает движение задним ходом» не має стандартного сигналу рукою; «повернуть налево» позначається круговими обертами; «снизить скорость или остановиться» — рухом руки вгору-вниз, а не нерухомою вертикальною рукою.", "img": "q147.png"}]);
